UPDATE sections SET data = '{"title": "Remodeling Pricing Across Two Counties", "eyebrow": "Where We Work", "counties": [{"url": "/fairfield-county/", "name": "Fairfield County", "image": "/images/areas/fairfield-county.jpg", "phone": "(203) 919-9616", "towns": ["Greenwich", "Stamford", "Norwalk", "Westport", "Darien", "New Canaan", "Fairfield", "Ridgefield"], "cta_label": "Learn more about Fairfield County", "town_links": {"Westport": "/fairfield-county/westport-ct/", "Greenwich": "/fairfield-county/greenwich-ct/"}, "description": "Home remodeling throughout Fairfield County, from waterfront renovations in Westport and Darien to kitchens, baths, basements, and additions in Greenwich, Stamford, Norwalk, and nearby towns.", "extra_towns": ["Bethel", "Bridgeport", "Brookfield", "Danbury", "Easton", "Monroe", "Newtown", "Shelton", "Stratford", "Trumbull", "Weston", "Wilton"]}, {"url": "/new-haven-county/", "name": "New Haven County", "image": "/images/areas/new-haven-county.jpg", "phone": "(203) 466-9148", "towns": ["Orange", "New Haven", "Hamden", "Branford", "Guilford", "Madison", "Woodbridge", "Milford"], "cta_label": "Learn more about New Haven County", "town_links": {"Orange": "/new-haven-county/orange-ct/", "New Haven": "/new-haven-county/new-haven-ct/"}, "description": "Home remodeling across New Haven County from our Orange office, including kitchens, bathrooms, basements, additions, flooring, and full-home improvements in Orange, New Haven, Hamden, Branford, Guilford, Milford, and nearby towns.", "extra_towns": ["Ansonia", "Bethany", "Cheshire", "Derby", "East Haven", "North Haven", "Oxford", "Seymour", "Wallingford", "Waterbury", "West Haven"]}], "subtitle": "We serve homeowners across Fairfield County and New Haven County with clear scopes, realistic allowances, and project planning that reflects local conditions.", "highlight_text": null}', updated_at = NOW() WHERE id = 3287;
