UPDATE sections SET data = '{"rows": [{"label": "Basic", "notes": "Cabinet refacing or stock cabinets, new countertops, updated appliances, paint", "price": "$25,000-$50,000"}, {"label": "Mid-Range", "notes": "New cabinets, stone countertops, new flooring, appliances, updated lighting", "price": "$50,000-$90,000"}, {"label": "High-End", "notes": "Custom or semi-custom cabinets, layout changes, premium appliances, full finishes", "price": "$90,000-$150,000"}, {"label": "Full Custom", "notes": "Fully custom cabinetry, structural changes, imported materials, high-end fixtures", "price": "$150,000-$250,000+"}], "title": "Kitchen Remodeling Cost in Connecticut", "columns": ["Scope", "Cost Range", "What''s Typically Included"], "subtitle": "Kitchen remodeling in Connecticut ranges from $25,000 for a basic cabinet and countertop update to $250,000 or more for a fully custom renovation with structural changes and imported materials. Ranges are illustrative for typical Connecticut projects. Final pricing depends on scope, materials, site conditions, and permit fees. Detailed written estimate provided before any work begins."}', updated_at = NOW() WHERE id = 5862;
UPDATE sections SET data = '{"title": "Kitchen Remodeling Across Two Counties", "eyebrow": "Where We Work", "counties": [{"url": "/fairfield-county/", "name": "Fairfield County", "image": "https://builtwell-api.petararsic.rs/storage/media/cgIlih2qYCeb09TCKKqHfgQmqX4dKGCLC7nBlbR4.webp", "phone": "(203) 919-9616", "towns": ["Greenwich", "Stamford", "Norwalk", "Westport", "Darien", "New Canaan", "Fairfield", "Ridgefield", "Trumbull"], "cta_label": "Learn more about Fairfield County", "image_alt": "Fairfield County, Connecticut — kitchen remodeling service area for BuiltWell CT", "town_links": {"Trumbull": "/fairfield-county/", "Westport": "/fairfield-county/westport-ct/", "Greenwich": "/fairfield-county/greenwich-ct/"}, "description": "Kitchen remodeling across Fairfield County, from custom chef kitchens in Greenwich and Westport to practical layout upgrades in Norwalk and Stamford. We handle every phase of the build in house.", "extra_towns": ["Bethel", "Bridgeport", "Brookfield", "Danbury", "Easton", "Monroe", "New Fairfield", "Newtown", "Redding", "Shelton", "Sherman", "Stratford", "Weston", "Wilton"]}, {"url": "/new-haven-county/", "name": "New Haven County", "image": "https://builtwell-api.petararsic.rs/storage/media/o9h97QoSRhwfHokAJYAk4HWV7Ef7HmpoY6K7yuhi.webp", "phone": "(203) 466-9148", "towns": ["Orange", "New Haven", "Hamden", "Branford", "Guilford", "Madison", "Woodbridge", "Milford", "Cheshire"], "cta_label": "Learn more about New Haven County", "image_alt": "New Haven County, Connecticut — kitchen remodeling service area for BuiltWell CT", "town_links": {"Orange": "/new-haven-county/orange-ct/", "New Haven": "/new-haven-county/new-haven-ct/"}, "description": "Kitchen remodeling across New Haven County, from our Orange, CT office. We modernize galley kitchens, open up floor plans, and deliver full gut renovations tailored to the local housing stock.", "extra_towns": ["Ansonia", "Beacon Falls", "Bethany", "Derby", "East Haven", "Meriden", "Middlebury", "Naugatuck", "North Branford", "North Haven", "Oxford", "Prospect", "Seymour", "Southbury", "Wallingford", "Waterbury", "West Haven", "Wolcott"]}], "subtitle": "We provide kitchen remodeling throughout Fairfield and New Haven Counties, with dedicated teams serving both regions.", "note_html": "Not sure if we cover your area? <a href=\\\\"/contact/\\\\">Contact our Connecticut remodeling team</a> and we&#39;ll let you know.", "highlight_text": "Two Counties"}', updated_at = NOW() WHERE id = 5867;
UPDATE sections SET data = '{"title":"Kitchen Remodeling Questions","items":[{"question":"Do I need a permit for a kitchen remodel in Connecticut?","answer":"Yes. Most kitchen remodeling projects in Connecticut require permits, particularly when the work involves electrical, plumbing, or structural modifications. Even cosmetic renovations that include new electrical outlets, relocated fixtures, or new plumbing connections will typically require a permit in most Connecticut towns. Some towns require separate permits for electrical, plumbing, and building work, each with their own inspections. We handle all permit applications and coordinate every required inspection as part of the project; you don''t need to manage that process yourself. If your town has a historic district and your property falls within it, we''ll identify that during the planning phase and account for any additional review requirements."},{"question":"How long does a kitchen remodel take in CT, including cabinet lead times?","answer":"Active construction on a Connecticut kitchen remodel takes six to twelve weeks depending on the scope of work. However, cabinet lead time needs to be added to that figure. Custom cabinets ordered in Connecticut typically require eight to twelve weeks to be manufactured and delivered before construction can begin. Semi-custom cabinets, which offer many of the same configuration options at a lower cost, reduce that window to four to six weeks. Stock cabinets are available much faster and can work well for basic to mid-range renovations. During the planning phase, we finalize your cabinet selections and order immediately so the lead time runs concurrently with other pre-construction work. Your written proposal includes a complete project schedule that accounts for all lead times."},{"question":"Can I do the design consultation remotely before the on-site visit?","answer":"Yes. We offer initial consultations via Google Meet or Zoom. You can share photos and measurements of your current kitchen, walk us through what you''re hoping to accomplish, and get preliminary cost guidance, all before scheduling an in-person visit. Many homeowners find this useful for narrowing down scope and confirming budget ranges before committing to an on-site assessment. The remote consultation is free and carries no obligation. If you decide to move forward, we schedule the in-person visit to take detailed measurements and assess conditions that a remote conversation can''t fully capture."},{"question":"Can I stay in my home during a kitchen remodel?","answer":"Yes, most homeowners remain in their homes throughout the remodeling process. We install dust barriers to contain debris and protect the rest of your home, and we clean up at the end of every workday. You will need a plan for temporary cooking and food preparation during the construction period; most homeowners use a microwave, a hot plate, or order out, and we can give you a realistic sense of how long you''ll be without a functioning kitchen based on your specific project scope. Access to a second bathroom for hand washing is helpful but not required. We''ll walk through what to expect from daily life during the project before construction begins so there are no surprises."},{"question":"What does a full kitchen remodel include?","answer":"A full-scope kitchen remodel with us includes demolition and removal of all existing cabinetry, countertops, and flooring; structural assessment and any required framing or structural modifications; new cabinetry installation with hardware; countertop fabrication and installation; backsplash tile work; new flooring with proper underlayment; all electrical work including new circuits and lighting; all plumbing including sink, dishwasher, and disposal connections; appliance coordination and installation; interior painting within the kitchen space; all drywall patching and finish work; permit applications and inspection coordination; daily cleanup throughout the project; and a final walkthrough. Abatement of hazardous materials, if asbestos or lead is discovered during demolition, is handled as part of the project with proper certification and documentation."},{"question":"How do I choose between custom, semi-custom, and stock cabinets?","answer":"Stock cabinets come in fixed sizes and finishes and are the most affordable option, typically available within one to two weeks. They work well for standard kitchen layouts where the existing dimensions align with available stock sizes. Semi-custom cabinets offer the same build quality as custom with more size, finish, and hardware options, and typically arrive in four to six weeks. Custom cabinets are built to your exact specifications - any size, any finish, any interior configuration - and require eight to twelve weeks for manufacturing. During our planning phase, we''ll walk you through all three options with pricing so you can make an informed decision based on your budget, timeline, and design goals."},{"question":"Do you offer financing for kitchen remodeling projects?","answer":"Yes. We offer flexible financing through GreenSky, which allows you to get approved in about 60 seconds (through GreenSky, subject to credit approval) and start your project right away. Financing options include low monthly payments and promotional periods depending on the plan you choose. We can walk you through the options during your consultation so you have a clear picture of both the project cost and the monthly payment before you commit to anything."},{"question":"What happens if you find unexpected issues behind the walls during demolition?","answer":"It happens regularly in Connecticut homes, especially those built before 2000. Common findings include outdated electrical wiring, deteriorated plumbing, water damage, asbestos floor tiles, or lead paint. When we discover something unexpected, we contact you that same day, explain what we found, present your options with clear costs, and wait for your approval before proceeding. We don''t make decisions about your home without your input. Any additional work is documented in a change order with a specific cost and timeline impact so there are no surprises on the final invoice."}]}', updated_at = NOW() WHERE id = 5868;
