UPDATE sections SET data = '{"rows": [{"label": "Single-room addition (bedroom, office)", "notes": "Foundation, framing, roofing, siding, electrical, HVAC, drywall, flooring, finishes", "price": "$80,000–$150,000"}, {"label": "Family room or living space addition", "notes": "Larger footprint, structural tie-in, matching roofline, full mechanical systems", "price": "$100,000–$180,000"}, {"label": "Kitchen bump-out (100-200 sq ft)", "notes": "Foundation extension, framing, plumbing, electrical, countertops, cabinets", "price": "$60,000–$120,000"}, {"label": "Second-story addition", "notes": "Structural reinforcement, full second floor, roofing, all systems, finishes", "price": "$150,000–$300,000+"}, {"label": "Garage conversion to living space", "notes": "Insulation, drywall, flooring, HVAC, electrical, windows, finishes", "price": "$50,000–$100,000"}, {"label": "Attached garage addition", "notes": "Foundation, framing, roofing, garage door, electrical, optional living space above", "price": "$60,000–$130,000"}, {"label": "Sunroom or three-season room", "notes": "Foundation, framing, windows, insulation, electrical, flooring, finishes", "price": "$50,000–$110,000"}], "title": "Home Addition Costs in Connecticut", "columns": ["Scope", "Cost Range", "What''s Typically Included"], "subtitle": "Home additions in Connecticut cost $150 to $400 per square foot all-in, covering design coordination, permits, foundation, framing, mechanical systems, and finishes. Most residential projects fall between $80,000 and $300,000 depending on type and scope. Ranges are illustrative for typical Connecticut projects. Final pricing depends on scope, materials, site conditions, and permit fees. Detailed written estimate provided before any work begins.", "energize_note": "New construction additions often qualify for energy rebates through Energize CT on insulation, HVAC systems, and windows. Visit energizect.com for current programs.", "below_table_note": "These figures include structural engineering, permits, foundation work, and all construction through final finishes. Costs vary by town based on permit fees, local zoning requirements, and site conditions.", "energize_note_html": "New construction additions often qualify for energy rebates through Energize CT on insulation, HVAC systems, and windows. <a href=\\\\"https://energizect.com\\\\" target=\\\\"_blank\\\\" rel=\\\\"noopener noreferrer\\\\">Visit Energize CT</a> for current programs."}', updated_at = NOW() WHERE id = 6237;
UPDATE sections SET data = '{"note": null, "title": "Home Additions Across Two Counties", "eyebrow": "Where We Work", "counties": [{"url": "/fairfield-county/", "name": "Fairfield County", "image": "https://builtwell-api.petararsic.rs/storage/media/cgIlih2qYCeb09TCKKqHfgQmqX4dKGCLC7nBlbR4.webp", "phone": "(203) 919-9616", "towns": ["Greenwich", "Stamford", "Norwalk", "Westport", "Darien", "New Canaan", "Fairfield", "Ridgefield"], "cta_label": "Learn more about Fairfield County", "image_alt": "Fairfield County, Connecticut — home additions service area for BuiltWell CT", "town_links": {"Westport": "/fairfield-county/westport-ct/", "Greenwich": "/fairfield-county/greenwich-ct/"}, "description": "Home additions across Fairfield County, from second story additions in Greenwich and Westport to bump outs and in-law suites in Norwalk and Stamford. We manage permits, structural work, and finishes in house.", "extra_towns": ["Bethel", "Bridgeport", "Brookfield", "Danbury", "Easton", "Monroe", "New Fairfield", "Newtown", "Redding", "Shelton", "Sherman", "Stratford", "Trumbull", "Weston", "Wilton"]}, {"url": "/new-haven-county/", "name": "New Haven County", "image": "https://builtwell-api.petararsic.rs/storage/media/o9h97QoSRhwfHokAJYAk4HWV7Ef7HmpoY6K7yuhi.webp", "phone": "(203) 466-9148", "towns": ["Orange", "New Haven", "Hamden", "Branford", "Guilford", "Madison", "Woodbridge", "Milford"], "cta_label": "Learn more about New Haven County", "image_alt": "New Haven County, Connecticut — home additions service area for BuiltWell CT", "town_links": {"Orange": "/new-haven-county/orange-ct/", "New Haven": "/new-haven-county/new-haven-ct/"}, "description": "Home additions across New Haven County, from our Orange, CT office. We add square footage to your home with seamless design integration, handling zoning, structural engineering, and construction start to finish.", "extra_towns": ["Ansonia", "Beacon Falls", "Bethany", "Cheshire", "Derby", "East Haven", "Meriden", "Middlebury", "Naugatuck", "North Branford", "North Haven", "Oxford", "Prospect", "Seymour", "Southbury", "Wallingford", "Waterbury", "West Haven", "Wolcott"]}], "subtitle": "We build home additions throughout Fairfield and New Haven Counties, with dedicated teams serving both regions.", "note_html": "Not sure if we cover your area? <a href=\\\\"/contact/\\\\">Contact our Connecticut remodeling team</a> and we''ll let you know.", "highlight_text": "Two Counties"}', updated_at = NOW() WHERE id = 6242;
UPDATE sections SET data = '{"title":"Home Addition Questions","items":[{"question":"How much does a home addition cost in Connecticut?","answer":"Home additions in Connecticut cost between $150 and $400 per square foot all-in, with most projects falling between $80,000 and $300,000. The type of addition is the biggest cost driver. A first-floor bedroom addition on a straightforward lot with a standard foundation will come in toward the lower end of the range. A second-story addition that requires reinforcing the existing structure, or a project with complex rooflines, custom finishes, and premium materials, will trend toward the higher end or above it. Other factors that affect cost in Connecticut specifically include site conditions like ledge rock or high water tables, permit fees that vary by town, and whether your project requires zoning board approval or historic commission review. We provide a detailed written estimate after the consultation and site visit, with exact numbers rather than ranges."},{"question":"How long does a home addition take to build?","answer":"Plan for a total timeline of four to six months from the start of design to project completion. Permit review in Connecticut typically takes two to six weeks depending on the town and the complexity of the application. Active construction runs eight to sixteen weeks from permit approval. Second-story additions, complex roofline work, and projects that require zoning board review trend toward the longer end of both phases. We give you a specific project schedule before construction begins. The schedule shows each phase of work, when inspections are required, and the sequence of trades so you know what to expect and when. We update you daily during the build."},{"question":"Do I need zoning approval for a home addition in CT?","answer":"Most home additions in Connecticut require at least a building permit, and many also require zoning approval. Zoning review is typically triggered when an addition changes the footprint of the structure, increases lot coverage, or places the building closer to property lines than the town''s setback rules allow. Towns across Fairfield and New Haven counties each have their own setback distances, maximum lot coverage percentages, and height restrictions. Greenwich, Darien, and New Canaan are among the most restrictive. Some towns also have additional review layers: homes in historic districts in New Haven, Guilford, and Ridgefield may need approval from a historic commission before the building department will issue a permit. We research your property''s zoning status and applicable rules before design begins. If your project requires a variance or special permit, we work with you through that process."},{"question":"Can I stay in my home during an addition project?","answer":"Yes. Most homeowners remain in their homes throughout the addition process. The tie-in to your existing structure is planned and sequenced carefully so your home stays dry and livable while work is underway. We install temporary weather protection at all connection points and maintain dust barriers inside. The level of disruption depends on the type of addition. A first-floor addition on the side of the house is less disruptive than a second-story addition that requires work above your living space. We walk through what to expect before construction begins so there are no surprises."},{"question":"What types of home additions do you build?","answer":"We build bedroom additions and primary suite additions, family room and living space additions, sunrooms and three-season rooms, first-floor additions that expand the main level without stair complications, second-story additions over an existing first-floor footprint, kitchen bump-outs that add 100 to 200 square feet of working space, garage conversions into finished living space, and attached garage additions with or without living space above. Each type has different structural, permitting, and cost considerations that we review during the consultation."},{"question":"Will the addition match the rest of my home?","answer":"That is one of the primary goals of every addition we build. The addition is designed to integrate structurally and visually with your existing home. That means matching rooflines, siding profiles, window styles, and interior trim so the new space looks like it was always part of the house. We coordinate with architects and structural engineers as part of the project scope to ensure the design achieves this. During the planning phase, we identify specific materials needed to match your existing finishes and source them before construction begins."},{"question":"Do you handle the architectural plans and engineering?","answer":"Yes. We coordinate with architects and structural engineers as part of the project scope, so you are not left managing multiple separate contractors. The structural engineering, architectural plans, and permit drawings are all handled within our project management. If you already have an architect, we are happy to work with them. If you need one, we have established relationships with architects experienced in Connecticut residential additions."},{"question":"Do you offer financing for home addition projects?","answer":"Yes. We offer flexible financing through GreenSky, which allows you to get approved in about 60 seconds (through GreenSky, subject to credit approval) and start your project right away. Financing options include low monthly payments and promotional periods depending on the plan you choose. Given the size of most addition projects, financing can make it practical to move forward sooner rather than waiting. We can walk you through the options during your consultation so you have a clear picture of both the project cost and the monthly payment before you commit to anything."}]}', updated_at = NOW() WHERE id = 6243;
