UPDATE sections SET data = '{"title": "Our Portfolio Is Coming Soon", "headline": "Our Portfolio Is Coming Soon", "subtitle": "BuiltWell CT is a brand-new Connecticut remodeling company built on 15+ years of remodeling and restoration experience. Full case studies will be published here as each project wraps.", "cta_primary": {"url": "/free-consultation/", "label": "Get Your Free Estimate"}, "subheadline": "BuiltWell CT is a brand-new Connecticut remodeling company built on 15+ years of remodeling and restoration experience. We''re finishing our first projects right now — full case studies, before-and-after galleries, and homeowner stories will be published here as each project wraps. Be one of our first customers and join the portfolio.", "cta_secondary": {"url": "tel:2039199616", "label": "Fairfield: (203) 919-9616"}, "title_highlight": "Projects", "background_image": "/services/kitchen-remodeling-ct.jpg"}', updated_at = NOW() WHERE id = 6249;
