UPDATE sections SET data = '{"rows": [{"label": "LVP (Luxury Vinyl Plank)", "notes": "Basements, kitchens, high-traffic areas, moisture-prone spaces", "price": "$6–$14 per sq ft"}, {"label": "Solid Hardwood", "notes": "Living rooms, dining rooms, bedrooms, above-grade only", "price": "$12–$25 per sq ft"}, {"label": "Engineered Hardwood", "notes": "Basements, areas with seasonal humidity changes", "price": "$8–$18 per sq ft"}, {"label": "Tile", "notes": "Bathrooms, kitchens, entryways", "price": "$12–$25 per sq ft"}, {"label": "Carpet", "notes": "Bedrooms, basement recreation rooms", "price": "$4–$12 per sq ft"}], "title": "Flooring Cost in Connecticut", "columns": ["Flooring Type", "Installed Cost", "Best Applications"], "subtitle": "Flooring installation in Connecticut costs $6 to $25 per square foot installed depending on the material, with most projects falling between these ranges based on the specific product and subfloor conditions. Ranges are illustrative for typical Connecticut projects. Final pricing depends on scope, materials, site conditions, and permit fees. Detailed written estimate provided before any work begins.", "disclaimer": "These ranges reflect installed cost including materials and labor. Subfloor repair, removal of multiple flooring layers, and custom patterns are priced separately.", "below_table_note": "These ranges reflect installed cost including materials and labor. Subfloor repair, removal of multiple flooring layers, and custom patterns are priced separately."}', updated_at = NOW() WHERE id = 6279;
UPDATE sections SET data = '{"note": "Not sure if we cover your area? Contact our Connecticut remodeling team and we''ll let you know.", "title": "Flooring Installation Across Two Counties", "eyebrow": "Where We Work", "counties": [{"url": "/fairfield-county/", "name": "Fairfield County", "image": "https://builtwell-api.petararsic.rs/storage/media/cgIlih2qYCeb09TCKKqHfgQmqX4dKGCLC7nBlbR4.webp", "phone": "(203) 919-9616", "towns": ["Greenwich", "Stamford", "Norwalk", "Westport", "Darien", "New Canaan", "Fairfield", "Ridgefield"], "cta_label": "Learn more about Fairfield County", "image_alt": "Fairfield County, Connecticut — flooring installation service area for BuiltWell CT", "town_links": {"Westport": "/fairfield-county/westport-ct/", "Greenwich": "/fairfield-county/greenwich-ct/"}, "description": "Flooring installation across Fairfield County, from wide plank hardwood in Greenwich and Westport to durable LVP and tile in Norwalk and Stamford. We handle demolition, subfloor prep, and install in house.", "extra_towns": ["Bethel", "Bridgeport", "Brookfield", "Danbury", "Easton", "Monroe", "New Fairfield", "Newtown", "Redding", "Shelton", "Sherman", "Stratford", "Trumbull", "Weston", "Wilton"]}, {"url": "/new-haven-county/", "name": "New Haven County", "image": "https://builtwell-api.petararsic.rs/storage/media/o9h97QoSRhwfHokAJYAk4HWV7Ef7HmpoY6K7yuhi.webp", "phone": "(203) 466-9148", "towns": ["Orange", "New Haven", "Hamden", "Branford", "Guilford", "Madison", "Woodbridge", "Milford"], "cta_label": "Learn more about New Haven County", "image_alt": "New Haven County, Connecticut — flooring installation service area for BuiltWell CT", "town_links": {"Orange": "/new-haven-county/orange-ct/", "New Haven": "/new-haven-county/new-haven-ct/"}, "description": "Flooring installation across New Haven County, from our Orange, CT office. We replace worn carpet, refinish existing hardwood, and install new flooring throughout homes of every era and layout.", "extra_towns": ["Ansonia", "Beacon Falls", "Bethany", "Cheshire", "Derby", "East Haven", "Meriden", "Middlebury", "Naugatuck", "North Branford", "North Haven", "Oxford", "Prospect", "Seymour", "Southbury", "Wallingford", "Waterbury", "West Haven", "Wolcott"]}], "subtitle": "We install flooring throughout Fairfield and New Haven Counties, both as standalone projects and as part of larger kitchen, bathroom, and basement renovations.", "highlight_text": "Two Counties"}', updated_at = NOW() WHERE id = 6284;
UPDATE sections SET data = '{"items":[{"question":"What is the best flooring for Connecticut homes?","answer":"The best flooring depends on the room, the level of the home, and the specific moisture conditions at your property. For above-grade living rooms, dining rooms, and bedrooms, solid hardwood is a proven choice that holds up to Connecticut''s climate when properly acclimated and finished. For kitchens, entryways, and high-traffic areas above grade, LVP and tile both work well and handle regular moisture exposure from cooking, foot traffic, and weather tracked in from outside. For basements and below-grade spaces, LVP is the most reliable choice in Connecticut. For bedrooms, carpet remains popular and appropriate above grade where moisture exposure is not a factor. Coastal homes near Long Island Sound may need to avoid solid hardwood in areas of elevated ambient humidity even above grade, and we assess those conditions at the consultation."},{"question":"How long does flooring installation take?","answer":"Most residential flooring projects complete in two to five days. A single room takes one to two days including subfloor preparation, installation, and trim work. Multi-room installations covering 250 to 600 square feet typically take two to three days. Full-floor or whole-home installations covering 600 to 1,200 square feet take three to five days. Large whole-home projects or those with significant subfloor repairs may extend to seven to ten days. If you are installing solid hardwood, add three to five days for the required acclimation period before installation begins. When flooring is part of a larger renovation, the flooring timeline is embedded in the overall project schedule and does not typically extend the overall duration."},{"question":"Can you install new flooring over existing flooring?","answer":"In some cases, yes. LVP and engineered hardwood can often be installed directly over existing hard surfaces provided the subfloor is level, structurally sound, and within acceptable moisture parameters. We assess each situation individually. The key factors are whether the existing surface is level enough to avoid telegraphing irregularities through the new floor, whether the added height at thresholds and doors creates problems, and whether the existing material is adhered securely. In cases where overlay installation is appropriate, it saves the cost and time of removal. In cases where it is not, removal is the right choice and we will tell you why. We do not cover up problems."},{"question":"What is the difference between solid and engineered hardwood?","answer":"Solid hardwood is milled from a single piece of wood, typically three-quarters of an inch thick, and can be sanded and refinished multiple times over its lifetime. It performs best in above-grade rooms with stable humidity. Engineered hardwood is constructed with a real wood veneer layer bonded over a plywood core. The cross-layer construction makes it significantly more resistant to the expansion and contraction that humidity changes cause in solid wood. Engineered hardwood is appropriate for below-grade spaces, rooms over concrete slabs, and Connecticut homes where seasonal humidity swings are pronounced. It can typically be refinished once or twice depending on the veneer thickness. The right choice depends on where in your home the flooring is going and what the moisture conditions are."},{"question":"Do I need to move furniture before flooring installation?","answer":"We move standard furniture within the work area as part of the installation. This includes sofas, chairs, tables, beds, dressers, and similar household furniture. Heavy or specialty items such as grand pianos, gun safes, large antique armoires, or other exceptionally heavy pieces require specialty movers that we can help you coordinate in advance. Disconnecting and reconnecting appliances in the kitchen is part of the scope when flooring extends into kitchen areas. Anything mounted to walls, like bookcases that are anchored or built-in units, should be discussed at the consultation so we can plan accordingly. We will let you know at the proposal stage exactly what we will handle and if there is anything that needs separate coordination."},{"question":"Does new flooring increase home value in Connecticut?","answer":"Yes. Updated flooring is consistently rated among the top home improvements for return on investment by real estate professionals. In Connecticut specifically, hardwood flooring in living areas and LVP in kitchens, basements, and high-traffic zones are the combinations buyers expect to see. Outdated or damaged flooring is one of the first things buyers notice during showings, and it directly affects both perceived value and offer prices. Refinished or new hardwood floors in Fairfield and New Haven County homes regularly contribute to faster sales and stronger offers."},{"question":"Do you offer financing for flooring projects?","answer":"Yes. We offer flexible financing through GreenSky, which allows you to get approved in about 60 seconds (through GreenSky, subject to credit approval) and start your project right away. Financing options include low monthly payments and promotional periods depending on the plan you choose. We can walk you through the options during your consultation so you have a clear picture of both the project cost and the monthly payment before you commit to anything."},{"question":"What happens if you find unexpected issues under the existing flooring?","answer":"It happens regularly in Connecticut homes, especially those built before 1980. Common findings include water-damaged subfloor sections, asbestos-containing floor tiles, mold from prior leaks, or subfloor framing that has deteriorated. When we discover something unexpected, we contact you that same day, explain what we found, present your options with clear costs, and wait for your approval before proceeding. Any additional work is documented in a change order with a specific cost and timeline impact so there are no surprises on the final invoice."}],"title":"Flooring Installation Questions"}', updated_at = NOW() WHERE id = 6285;
