UPDATE sections SET data = '{"image": "/images/areas/builtwell-on-site-ct-residential-project.jpg", "title": "Your Neighborhood, Our Neighborhood", "content": "We are headquartered right here in Orange on Boston Post Road. That means we are not commuting an hour to get to your house. When you call our office, you are reaching people who drive the same roads you do, who know the building inspector by name, and who understand how the town operates.\\\\n\\\\nThat proximity shows up in faster response times, smoother permitting, and a level of familiarity with the area that out-of-town contractors simply do not have. We have worked on Race Brook Road, on Racebrook Farms, on Grassy Hill, and in the neighborhoods off of Orange Center Road. When a homeowner two streets from our office calls about a project, it is personal. This is our community, and the quality of our work here is our most visible calling card.", "image_alt": "BuiltWell CT crew on-site at a Connecticut residential remodeling project — two branded vans, scaffolding at the front entry, and active job-site setup at a colonial home", "image_position": "left"}', updated_at = NOW() WHERE id = 6775;
UPDATE sections SET data = '{"rows": [{"label": "Basic", "notes": "Cabinet refacing, new counters, appliances, paint", "price": "$25,000 - $50,000"}, {"label": "Mid-Range", "notes": "New cabinets, countertops, flooring, appliances, lighting", "price": "$50,000 - $90,000"}, {"label": "High-End", "notes": "Custom cabinets, layout changes, premium appliances", "price": "$90,000 - $150,000+"}], "title": "Kitchen Remodeling Costs in Orange, CT", "columns": ["Tier", "Scope", "Typical Range"], "subtitle": "Orange''s 1960s-1980s housing stock means kitchen renovations frequently involve updating original electrical panels from 100 to 200 amps, replacing galvanized supply lines, and addressing asbestos-containing floor tiles - costs that are part of the scope, not surprises. Ranges are illustrative for typical Connecticut projects. Final pricing depends on scope, materials, site conditions, and permit fees. Detailed written estimate provided before any work begins."}', updated_at = NOW() WHERE id = 6778;
