UPDATE sections SET data = '{"rows": [{"label": "Basic", "notes": "Framing, drywall, basic flooring, lighting, paint", "price": "$25,000 - $45,000"}, {"label": "Mid-Range", "notes": "Multiple rooms, upgraded flooring, bathroom rough-in", "price": "$45,000 - $70,000"}, {"label": "High-End", "notes": "Full bathroom, wet bar, custom built-ins", "price": "$70,000 - $100,000+"}], "title": "Basement Finishing Costs in Orange, CT", "columns": ["Tier", "Scope", "Typical Range"], "subtitle": "Orange split-levels often have partially finished lower levels that make excellent candidates for full finishing. Moisture assessment is standard before framing begins. Ranges are illustrative for typical Connecticut projects. Final pricing depends on scope, materials, site conditions, and permit fees. Detailed written estimate provided before any work begins."}', updated_at = NOW() WHERE id = 6780;
