UPDATE sections SET data = '{"rows": [{"label": "Hourly Rate", "notes": "Custom trim, built-ins, shelving, wainscoting", "price": "$75 - $150/hour"}, {"label": "Crown Molding", "notes": "Per linear foot, installed", "price": "$8 - $25/LF"}, {"label": "Custom Built-Ins", "notes": "Bookcases, window seats, mudroom storage", "price": "$3,000 - $15,000+"}], "title": "Interior Carpentry Costs in Orange, CT", "columns": ["Scope", "Details", "Typical Range"], "subtitle": "Orange colonials and split-levels often have original trim and built-in cabinetry that homeowners want preserved or updated during renovation. Custom millwork matching these mid-century profiles adds both material cost and lead time. Ranges are illustrative for typical Connecticut projects. Final pricing depends on scope, materials, site conditions, and permit fees. Detailed written estimate provided before any work begins."}', updated_at = NOW() WHERE id = 6784;
