UPDATE sections SET data = '{"rows": [{"label": "Basic Refresh", "notes": "Cabinet refacing, new countertops, appliances, paint", "price": "$25,000 - $50,000"}, {"label": "Mid-Range", "notes": "New cabinets, countertops, flooring, appliances, lighting", "price": "$50,000 - $90,000"}, {"label": "High-End", "notes": "Full custom, layout changes, premium materials", "price": "$90,000 - $150,000+"}], "title": "Kitchen Remodeling Costs in New Haven, CT", "columns": ["Tier", "Scope", "Typical Range"], "subtitle": "Pre-war premium: In East Rock, Prospect Hill, Wooster Square, Beaver Hills, and Westville, projects in the older housing stock routinely add $15,000 to $40,000 to the above ranges for lead abatement, knob-and-tube rewiring, asbestos testing and licensed abatement where required, and steam system coordination. Ranges are illustrative for typical Connecticut projects. Final pricing depends on scope, materials, site conditions, and permit fees. Detailed written estimate provided before any work begins."}', updated_at = NOW() WHERE id = 7169;
UPDATE sections SET data = '{"rows": [{"label": "Basic", "notes": "New fixtures, vanity, flooring, paint", "price": "$15,000 - $25,000"}, {"label": "Mid-Range", "notes": "Full gut, new tile, shower or tub, vanity, lighting", "price": "$25,000 - $55,000"}, {"label": "High-End", "notes": "Layout changes, premium fixtures, custom tile", "price": "$55,000 - $80,000+"}], "title": "Bathroom Remodeling Costs in New Haven, CT", "columns": ["Tier", "Scope", "Typical Range"], "subtitle": "Ranges are illustrative for typical Connecticut projects. Final pricing depends on scope, materials, site conditions, and permit fees. Detailed written estimate provided before any work begins."}', updated_at = NOW() WHERE id = 7170;
UPDATE sections SET data = '{"rows": [{"label": "Basic", "notes": "Framing, drywall, flooring, lighting, paint", "price": "$25,000 - $45,000"}, {"label": "Mid-Range", "notes": "Multiple rooms, upgraded flooring, bathroom rough-in", "price": "$45,000 - $70,000"}, {"label": "High-End", "notes": "Full bathroom, wet bar, custom built-ins", "price": "$70,000 - $100,000+"}], "title": "Basement Finishing Costs in New Haven, CT", "columns": ["Tier", "Scope", "Typical Range"], "subtitle": "Stone foundation basements in pre-1900 New Haven homes require moisture assessment and often interior drainage systems before framing begins. That work is scoped and priced separately and must be completed before any finish work can be planned. Ranges are illustrative for typical Connecticut projects. Final pricing depends on scope, materials, site conditions, and permit fees. Detailed written estimate provided before any work begins."}', updated_at = NOW() WHERE id = 7171;
UPDATE sections SET data = '{"rows": [{"label": "Solid Hardwood", "notes": "Living rooms, dining rooms, bedrooms", "price": "$12 - $25"}, {"label": "Engineered Hardwood", "notes": "Basements, moisture-prone areas", "price": "$8 - $18"}, {"label": "Luxury Vinyl Plank", "notes": "Basements, kitchens, high-traffic", "price": "$6 - $14"}, {"label": "Tile", "notes": "Bathrooms, kitchens, entryways", "price": "$12 - $25"}], "title": "Flooring Costs in New Haven, CT", "columns": ["Material", "Best For", "Installed Cost/sq ft"], "subtitle": "Many pre-war New Haven homes have original hardwood floors in good condition underneath carpet or vinyl installed in later decades. Where original floors can be refinished, that is almost always the right choice, both for cost and for architectural integrity. Ranges are illustrative for typical Connecticut projects. Final pricing depends on scope, materials, site conditions, and permit fees. Detailed written estimate provided before any work begins."}', updated_at = NOW() WHERE id = 7172;
