UPDATE sections SET data = '{"rows": [{"label": "Single-Room Project", "notes": "Site assessment, scope document, layout drawings, permit application, selections guidance", "price": "$2,500-$5,000"}, {"label": "Multi-Room Renovation", "notes": "All of the above for multiple spaces, coordination across trades", "price": "$5,000-$10,000"}, {"label": "Home Addition or Complex Project", "notes": "Structural engineering coordination, multiple permit applications, detailed drawings, zoning review", "price": "$8,000-$15,000"}], "title": "Remodeling Design and Planning Cost in Connecticut", "columns": ["Scope", "Cost Range", "What''s Typically Included"], "subtitle": "Design and planning fees in Connecticut range from $2,500 for a focused single-room project to $15,000 for a complex renovation or addition requiring structural engineering coordination, zoning review, and multiple permit applications. Ranges are illustrative for typical Connecticut projects. Final pricing depends on scope, materials, site conditions, and permit fees. Detailed written estimate provided before any work begins.", "below_table_note": "When planning is part of a full renovation we are also building, the fee is included in the overall project cost."}', updated_at = NOW() WHERE id = 7683;
