UPDATE sections SET data = '{"rows": [{"note": "Grab bars, threshold work, lever handles, improved lighting", "label": "Targeted Modifications", "notes": "Grab bars, threshold work, lever handles, improved lighting", "price": "$5,000–$10,000", "value": "$5,000–$10,000"}, {"note": "Walk-in shower with zero-threshold entry, grab bars, comfort-height toilet, non-slip tile", "label": "Bathroom Conversion", "notes": "Walk-in shower with zero-threshold entry, grab bars, comfort-height toilet, non-slip tile", "price": "$15,000–$30,000", "value": "$15,000–$30,000"}, {"note": "Doorway widening, ramp construction, bathroom conversion, lighting and hardware throughout", "label": "Full Home Modifications", "notes": "Doorway widening, ramp construction, bathroom conversion, lighting and hardware throughout", "price": "$30,000–$50,000", "value": "$30,000–$50,000"}], "title": "Accessibility Remodeling Cost in Connecticut", "columns": ["Scope", "Cost Range", "What''s Typically Included"], "subtitle": "Accessibility modification costs in Connecticut range from $5,000 for targeted modifications to $50,000 for full-home modifications covering multiple areas. A bathroom conversion typically falls between $15,000 and $30,000. Ranges are illustrative for typical Connecticut projects. Final pricing depends on scope, materials, site conditions, and permit fees. Detailed written estimate provided before any work begins.", "below_table_note": "These ranges reflect the scope of the work. We provide a specific cost after an on-site assessment because the actual conditions in your home determine what''s involved.", "energize_ct_note": "If your project includes a mini-split or HVAC upgrade, Connecticut homeowners may qualify for rebates through Energize CT. <a href=\\\\"https://energizect.com\\\\" target=\\\\"_blank\\\\" rel=\\\\"noopener noreferrer\\\\" style=\\\\"color: var(--gold); font-weight: 600;\\\\">Visit Energize CT</a> for current programs.", "energize_note_html": "If your project includes a mini-split or HVAC upgrade, Connecticut homeowners may qualify for rebates through Energize CT. <a href=\\\\"https://energizect.com\\\\" target=\\\\"_blank\\\\" rel=\\\\"noopener noreferrer\\\\">Visit Energize CT</a> for current programs."}', updated_at = NOW() WHERE id = 7802;
UPDATE sections SET data = '{"note": null, "title": "Accessibility Remodeling Across Two Counties", "eyebrow": "Where We Work", "counties": [{"url": "/fairfield-county/", "name": "Fairfield County", "image": "https://builtwell-api.petararsic.rs/storage/media/cgIlih2qYCeb09TCKKqHfgQmqX4dKGCLC7nBlbR4.webp", "phone": "(203) 919-9616", "towns": ["Greenwich", "Stamford", "Norwalk", "Westport", "Darien", "New Canaan", "Fairfield", "Ridgefield", "Trumbull"], "cta_label": "Learn more about Fairfield County", "image_alt": "Fairfield County, Connecticut — accessibility remodeling service area for BuiltWell CT", "town_links": {"Trumbull": "/fairfield-county/", "Westport": "/fairfield-county/westport-ct/", "Greenwich": "/fairfield-county/greenwich-ct/"}, "description": "Accessibility remodeling across Fairfield County, from aging in place upgrades in Greenwich and Westport to grab bars, ramps, and barrier free showers in Norwalk and Stamford. Safety built into every detail.", "extra_towns": ["Bethel", "Bridgeport", "Brookfield", "Danbury", "Easton", "Monroe", "New Fairfield", "Newtown", "Redding", "Shelton", "Sherman", "Stratford", "Weston", "Wilton"]}, {"url": "/new-haven-county/", "name": "New Haven County", "image": "https://builtwell-api.petararsic.rs/storage/media/o9h97QoSRhwfHokAJYAk4HWV7Ef7HmpoY6K7yuhi.webp", "phone": "(203) 466-9148", "towns": ["Orange", "New Haven", "Hamden", "Branford", "Guilford", "Madison", "Woodbridge", "Milford", "Cheshire"], "cta_label": "Learn more about New Haven County", "image_alt": "New Haven County, Connecticut — accessibility remodeling service area for BuiltWell CT", "town_links": {"Orange": "/new-haven-county/orange-ct/", "New Haven": "/new-haven-county/new-haven-ct/"}, "description": "Accessibility remodeling across New Haven County, from our Orange, CT office. We make homes safer and more comfortable with thoughtful modifications that maintain the look and feel of your space.", "extra_towns": ["Ansonia", "Beacon Falls", "Bethany", "Derby", "East Haven", "Meriden", "Middlebury", "Naugatuck", "North Branford", "North Haven", "Oxford", "Prospect", "Seymour", "Southbury", "Wallingford", "Waterbury", "West Haven", "Wolcott"]}], "subtitle": "We provide comfort and accessibility remodeling throughout Fairfield and New Haven Counties, with dedicated teams serving both regions.", "note_html": "Not sure if we cover your area? <a href=\\\\"/contact/\\\\">Contact our Connecticut remodeling team</a> and we''ll let you know.", "highlight_text": "Two Counties"}', updated_at = NOW() WHERE id = 7807;
UPDATE sections SET data = '{"title":"Comfort and Accessibility Questions","items":[{"question":"What accessibility modifications make the biggest difference?","answer":"The bathroom is consistently the highest-impact area for accessibility modifications. A zero-threshold walk-in shower eliminates the most common fall hazard in the home. Properly anchored grab bars at the shower, toilet, and tub provide reliable support where it''s needed most. A comfort-height toilet (17 to 19 inches from floor to seat, compared to the standard 15 inches) makes sitting and standing significantly easier for most people with limited mobility or joint pain. After the bathroom, lever-style door handles and faucet controls throughout the home are among the most cost-effective improvements."},{"question":"Do I need a permit for grab bars or accessibility modifications in Connecticut?","answer":"Most grab bar installations and targeted modifications \\\\u2014 lever handles, improved lighting, threshold ramping \\\\u2014 do not require building permits in Connecticut. Structural modifications, including doorway widening, ramp construction with footings, and any work that changes the plumbing layout during a bathroom conversion, typically do require permits. We assess the permitting requirements as part of every project and handle all applications where permits are needed. We''ve completed this work across Fairfield County and New Haven County and are familiar with the specific requirements in each town."},{"question":"Can accessibility features be added during a larger remodel?","answer":"Yes, and this is almost always the most cost-effective approach. Adding grab bar blocking inside walls during a bathroom remodel costs $200 to $400 in materials and labor at rough-in stage. Opening the finished wall later to install that blocking costs $1,000 to $2,000 or more, depending on tile and finish work affected. The same logic applies to doorway widening, ramp preparation, and exterior accessibility work. If a renovation project involves framing work near a doorway that will eventually need to be widened, doing it during the renovation costs far less than returning to it separately."},{"question":"How long do accessibility modifications take to complete?","answer":"Most accessibility projects take one to four weeks depending on scope. Targeted modifications like grab bars, lever handles, and improved lighting can be completed in a few days. A bathroom conversion \\\\u2014 tub to walk-in shower with grab bars, non-slip tile, and a comfort-height toilet \\\\u2014 typically takes two to three weeks. Full-home modifications covering doorway widening, ramp construction, bathroom conversion, and hardware and lighting throughout take three to four weeks. We provide a specific timeline in your proposal after the on-site assessment."},{"question":"When should I consider accessibility remodeling?","answer":"Comfort and accessibility remodeling is worth considering any time a family member''s mobility needs have changed, when you''re preparing a home for an aging parent to move in, when you want to make modifications now rather than face more disruptive changes later, or following a medical event where the home needs to be adapted to support recovery or ongoing care. Proactive modifications done during a larger renovation cost less than doing them separately, because the wall is already open and the trades are already on-site."},{"question":"How much do grab bars cost to install properly?","answer":"Grab bar installation is included in our targeted modifications scope, which ranges from $5,000 to $10,000 and covers grab bars, threshold work, lever handles, and improved lighting. The cost of proper grab bar installation depends on whether blocking exists behind the wall. If blocking was roughed in during original construction, installation is straightforward. If not, we open the wall, install solid blocking, close it back cleanly, and then mount the grab bar. A grab bar screwed into drywall with no backing will pull out under load \\\\u2014 we don''t install them that way."},{"question":"Can you convert a first-floor room to a bedroom and bathroom?","answer":"Yes. For homeowners where navigating stairs has become the primary difficulty, we assess the first-floor layout for bedroom and bathroom feasibility. In some Connecticut colonials, a formal dining room or study on the first floor can be converted to a bedroom, with a half-bath expanded or modified to accommodate showering \\\\u2014 eliminating the need to use stairs entirely for daily living. If existing first-floor layout doesn''t allow for conversion, our home additions service can create first-floor bedroom and bathroom square footage through a rear or side addition."},{"question":"Do you offer financing for accessibility remodeling projects?","answer":"Yes. We offer flexible financing through GreenSky, which allows you to get approved in about 60 seconds (through GreenSky, subject to credit approval) and start your project right away. Financing options include low monthly payments and promotional periods depending on the plan you choose. We can walk you through the options during your consultation so you have a clear picture of both the project cost and the monthly payment before you commit to anything."}]}', updated_at = NOW() WHERE id = 7808;
