UPDATE sections SET data = '{"rows": [{"note": "Insulation upgrade, flooring, drywall, electrical, egress window", "label": "Basic Finishing", "notes": "Insulation upgrade, flooring, drywall, electrical, egress window", "price": "$50,000–$75,000", "value": "$50,000–$75,000"}, {"note": "Bedroom or office with closet, full egress, HVAC extension or mini-split, finishes", "label": "Full Living Space", "notes": "Bedroom or office with closet, full egress, HVAC extension or mini-split, finishes", "price": "$75,000–$120,000", "value": "$75,000–$120,000"}, {"note": "Structural dormer, additional headroom, full finishes, bathroom", "label": "Dormer Addition", "notes": "Structural dormer, additional headroom, full finishes, bathroom", "price": "$100,000–$150,000+", "value": "$100,000–$150,000+"}], "title": "Attic Conversion Cost in Connecticut", "columns": ["Scope", "Cost Range", "What''s Typically Included"], "eyebrow": "Investment", "subtitle": "Attic conversion costs in Connecticut range from $50,000 for a basic finished room to $150,000 or more for a full dormer addition with a bathroom and premium finishes. Ranges are illustrative for typical Connecticut projects. Final pricing depends on scope, materials, site conditions, and permit fees. Detailed written estimate provided before any work begins.", "energize_note": "Attic insulation is one of the most common qualifying upgrades under Eversource Home Energy Solutions. Connecticut homeowners can schedule a free energy audit and may receive insulation rebates through energizect.com.", "title_highlight": "Connecticut", "below_table_note": "All prices include labor and materials. Final cost depends on scope, selections, and site conditions.", "energize_note_html": "Attic insulation is one of the most common qualifying upgrades under Eversource Home Energy Solutions. Connecticut homeowners can schedule a free energy audit and may receive insulation rebates through <a href=\\\\"https://energizect.com\\\\" target=\\\\"_blank\\\\" rel=\\\\"noopener noreferrer\\\\">Energize CT</a>."}', updated_at = NOW() WHERE id = 8059;
UPDATE sections SET data = '{"note": null, "title": "Attic Conversions Across Two Counties", "eyebrow": "Where We Work", "counties": [{"url": "/fairfield-county/", "name": "Fairfield County", "image": "https://builtwell-api.petararsic.rs/storage/media/cgIlih2qYCeb09TCKKqHfgQmqX4dKGCLC7nBlbR4.webp", "phone": "(203) 919-9616", "towns": ["Greenwich", "Stamford", "Norwalk", "Westport", "Darien", "New Canaan", "Fairfield", "Ridgefield", "Trumbull"], "cta_label": "Learn more about Fairfield County", "image_alt": "Fairfield County, Connecticut — attic conversion service area for BuiltWell CT", "town_links": {"Trumbull": "/fairfield-county/", "Westport": "/fairfield-county/westport-ct/", "Greenwich": "/fairfield-county/greenwich-ct/"}, "description": "Attic conversions across Fairfield County, from bonus rooms in Greenwich and Westport to home offices and guest suites in Norwalk and Stamford. We handle insulation, dormers, and full buildouts in house.", "extra_towns": ["Bethel", "Bridgeport", "Brookfield", "Danbury", "Easton", "Monroe", "New Fairfield", "Newtown", "Redding", "Shelton", "Sherman", "Stratford", "Trumbull", "Weston", "Wilton"]}, {"url": "/new-haven-county/", "name": "New Haven County", "image": "https://builtwell-api.petararsic.rs/storage/media/o9h97QoSRhwfHokAJYAk4HWV7Ef7HmpoY6K7yuhi.webp", "phone": "(203) 466-9148", "towns": ["Orange", "New Haven", "Hamden", "Branford", "Guilford", "Madison", "Woodbridge", "Milford", "Cheshire"], "cta_label": "Learn more about New Haven County", "image_alt": "New Haven County, Connecticut — attic conversion service area for BuiltWell CT", "town_links": {"Orange": "/new-haven-county/orange-ct/", "New Haven": "/new-haven-county/new-haven-ct/"}, "description": "Attic conversions across New Haven County, from our Orange, CT office. We turn unused attic space into livable square footage, managing structural work, permits, and finishes from start to finish.", "extra_towns": ["Ansonia", "Beacon Falls", "Bethany", "Cheshire", "Derby", "East Haven", "Meriden", "Middlebury", "Naugatuck", "North Branford", "North Haven", "Oxford", "Prospect", "Seymour", "Southbury", "Wallingford", "Waterbury", "West Haven", "Wolcott"]}], "footnote": "Not sure if we cover your area? Contact our Connecticut remodeling team and we will let you know.", "subtitle": "We complete attic conversions throughout Fairfield and New Haven Counties, with dedicated teams serving both regions.", "note_html": "Not sure if we cover your area? <a href=\\\\"/contact/\\\\">Contact our Connecticut remodeling team</a> and we''ll let you know.", "highlight_text": "Two Counties"}', updated_at = NOW() WHERE id = 8064;
UPDATE sections SET data = '{"title":"Attic Conversion Questions","items":[{"question":"Can my attic be converted to living space?","answer":"Most Connecticut attics can be converted to living space, but the answer depends on four specific conditions: floor joist sizing and span, available headroom at the ridge, roof framing configuration, and access. Most can be addressed through construction. Joists can be sistered, dormers can add headroom, and new stairs can be built. Each has a cost that varies with the home. The floor joists are the most critical factor. In Connecticut homes built before 1990, attic joists are almost always sized for storage loads, not occupancy loads. Sistering new framing alongside existing members to increase structural capacity is the standard fix. Headroom is the second gating factor. If your existing ridge height doesn''t allow 7 feet 6 inches of clear ceiling height over enough of the floor area, the space won''t qualify as habitable under Connecticut building code without a dormer. We measure this on-site and show you exactly what you''re working with."},{"question":"Do I need a dormer to finish my attic in Connecticut?","answer":"Not every attic requires a dormer, but many Connecticut colonials and cape cods do, particularly capes, where the roofline cuts sharply and limits usable headroom to a narrow strip at the ridge. Whether you need one depends on how much headroom your existing roofline provides at the ridge and how much usable floor area that headroom covers. Connecticut building code requires that at least half of a habitable attic''s floor area have a ceiling height of 7 feet 6 inches or more. In a standard colonial, the ridge is often high enough to meet this requirement without a dormer. In a cape, it''s rarely enough. When a dormer is needed, it adds cost but delivers proportionally more usable space and natural light. A shed dormer, which runs the full length of the roof, tends to be more cost-effective per square foot of headroom gained than a gable dormer."},{"question":"How is an attic conversion heated and cooled in Connecticut?","answer":"Attic conversions in Connecticut are most commonly heated and cooled with a ductless mini-split system, a wall-mounted unit that handles both heating and cooling without connecting to your home''s existing ductwork. Mini-splits are well-suited to attic spaces because they''re efficient, quiet, and allow independent temperature control separate from the rest of the house. Extending your existing forced-air system into the attic is possible in some homes, but it''s often impractical. The ductwork would need to run through unconditioned space to reach the attic, which reduces efficiency and can create condensation problems in Connecticut''s climate. In most cases, a mini-split is the cleaner and more reliable solution. The sizing of the mini-split matters. Attics gain heat quickly in summer due to roof exposure and lose it quickly in winter. We specify equipment based on the actual square footage, insulation levels, and window area of the finished space."},{"question":"How much does an attic conversion cost in Connecticut?","answer":"Attic conversion costs in Connecticut range from $50,000 for a basic finished room to $150,000 or more for a full dormer addition with a bathroom and premium finishes. The biggest cost variables are structural reinforcement, egress requirements, and whether headroom requires a dormer. A basic finishing with insulation upgrade, flooring, drywall, electrical, and egress window runs $50,000 to $75,000. A full living space with bedroom or office, closet, full egress, HVAC, and finishes runs $75,000 to $120,000. A dormer addition with additional headroom, full finishes, and bathroom runs $100,000 to $150,000 or more. These ranges assume standard joist reinforcement is needed, which it almost always is. We give you a specific number after an on-site assessment, not a range that leaves you guessing."},{"question":"How long does an attic conversion take in Connecticut?","answer":"Most attic conversions take six to twelve weeks of active construction to complete, with structural engineering review and permit approval adding another three to six weeks before construction begins. The total timeline from signed proposal to final walkthrough typically runs nine to eighteen weeks depending on the complexity of the project. Dormer additions and bathroom installations extend the timeline toward the upper end of that range. During the planning phase, we provide a detailed schedule so you know what to expect at every stage of the project."},{"question":"Do I need a permit for an attic conversion in Connecticut?","answer":"Yes. Attic conversions in Connecticut require building permits in every municipality we serve. The work involves structural modifications, electrical, insulation changes, and often plumbing, all of which require permits and inspections. Some towns require separate electrical, plumbing, and building permits, each with their own inspections. If your home is in a historic district, there may be additional design review requirements for exterior changes like dormers. We handle all permit applications and coordinate every required inspection as part of the project."},{"question":"What is included in an attic conversion?","answer":"An attic conversion includes structural assessment and joist reinforcement, insulation and air sealing upgrades, egress window or dormer installation, HVAC extension or mini-split installation, electrical wiring, drywall, flooring, and finish trim. Everything required to bring the space to code as habitable area is included in our scope. We start with a thorough structural assessment of joist sizing, roof framing, and load paths. Many Connecticut homes built between the 1950s and 1980s have attic floor joists sized for storage only. We account for reinforcement upfront rather than discovering it mid-construction."},{"question":"Do you offer financing for attic conversion projects?","answer":"Yes. We offer flexible financing through GreenSky, which allows you to get approved in about 60 seconds (through GreenSky, subject to credit approval) and start your project right away. Financing options include low monthly payments and promotional periods depending on the plan you choose. We can walk you through the options during your consultation so you have a clear picture of both the project cost and the monthly payment before you commit to anything."}]}', updated_at = NOW() WHERE id = 8065;
