UPDATE sections SET data = '{"variant":"homeowner_hub_funding_cards","eyebrow":"Funding and Assistance","title":"Connecticut Programs for Accessibility Modifications","highlight_text":"Accessibility","subtitle":"Connecticut homeowners can access six funding sources for accessibility modifications, including the CT Home Care Program, USDA Section 504 grants up to $10,000, VA housing grants, and IRS medical expense deductions for prescribed modifications.","surface":"dark","background_image":"\\\\/hero\\\\/builtwell-job-site-aerial-hero-ct.jpg","items":[{"title":"CT Home Care Program","description":"Administered by the CT Department of Social Services, this Medicaid waiver program covers home modifications for eligible seniors and adults with disabilities - including ramps, grab bars, and bathroom modifications.","url":"https:\\\\/\\\\/portal.ct.gov\\\\/dss\\\\/health-and-home-care\\\\/connecticut-home-care-program-for-elders\\\\/connecticut-home-care-program-for-elders-chcpe"},{"title":"USDA Section 504 Grants","description":"Available to very-low-income homeowners age 62 and older. Grants up to $10,000 for removing health and safety hazards, including accessibility modifications. Available in qualifying CT areas.","url":"https:\\\\/\\\\/www.rd.usda.gov\\\\/programs-services\\\\/single-family-housing-programs\\\\/single-family-housing-repair-loans-grants"},{"title":"VA SAH \\\\/ SHA Grants","description":"Veterans with service-connected disabilities may qualify for Specially Adapted Housing (SAH) or Special Housing Adaptation (SHA) grants - covering wheelchair ramps, roll-in showers, widened doorways, and more.","url":"https:\\\\/\\\\/www.va.gov\\\\/housing-assistance\\\\/disability-housing-grants\\\\/"},{"title":"Area Agencies on Aging","description":"Connecticut''s five Area Agencies on Aging administer local programs for home modification assistance. Coverage and eligibility vary by region. Contact your local AAA for current availability.","url":"https:\\\\/\\\\/portal.ct.gov\\\\/aginganddisability\\\\/content-pages\\\\/topics-a-z\\\\/area-agencies-on-aging"},{"title":"Medical Expense Deduction","description":"Home modifications prescribed by a physician as medically necessary may qualify as deductible medical expenses on federal taxes. Consult your tax advisor for eligibility and documentation requirements.","url":"https:\\\\/\\\\/www.irs.gov\\\\/taxtopics\\\\/tc502"},{"title":"GreenSky Financing","description":"For homeowners who do not qualify for assistance programs, we offer flexible financing through GreenSky. Get approved in about 60 seconds (through GreenSky, subject to credit approval) with competitive rates and manageable monthly payments. The Energize CT program, administered by Eversource and United Illuminating, offers rebates on insulation, HVAC, and appliance upgrades for Connecticut homeowners.","url":"https:\\\\/\\\\/www.greensky.com\\\\/"}]}', updated_at = NOW() WHERE id = 8345;
UPDATE sections SET data = '{"note": "Not sure if we cover your area? Contact our Connecticut remodeling team and we will let you know.", "title": "Our Service Areas", "eyebrow": "Where We Work", "counties": [{"url": "/fairfield-county/", "name": "Fairfield County", "image": "https://builtwell-api.petararsic.rs/storage/media/cgIlih2qYCeb09TCKKqHfgQmqX4dKGCLC7nBlbR4.webp", "phone": "(203) 919-9616", "towns": ["Greenwich", "Stamford", "Norwalk", "Westport", "Darien", "New Canaan", "Fairfield", "Ridgefield"], "cta_label": "Learn more about Fairfield County", "image_alt": "Fairfield County, Connecticut - home remodeling service area for BuiltWell CT", "town_links": [{"url": "/fairfield-county/greenwich-ct/", "name": "Greenwich"}, {"url": "/fairfield-county/westport-ct/", "name": "Westport"}], "description": "Serving all of Fairfield County with dedicated local crews. From Greenwich estates to Ridgefield colonials, we know the housing stock and building departments across the county.", "extra_towns": ["Trumbull", "Bethel", "Bridgeport", "Brookfield", "Danbury", "Easton", "Monroe", "New Fairfield", "Newtown", "Redding", "Shelton", "Sherman", "Stratford", "Weston", "Wilton"]}, {"url": "/new-haven-county/", "name": "New Haven County", "image": "https://builtwell-api.petararsic.rs/storage/media/o9h97QoSRhwfHokAJYAk4HWV7Ef7HmpoY6K7yuhi.webp", "phone": "(203) 466-9148", "towns": ["Orange", "New Haven", "Hamden", "Branford", "Guilford", "Madison", "Woodbridge", "Milford"], "cta_label": "Learn more about New Haven County", "image_alt": "New Haven County, Connecticut - home remodeling service area for BuiltWell CT", "town_links": [{"url": "/new-haven-county/orange-ct/", "name": "Orange"}, {"url": "/new-haven-county/new-haven-ct/", "name": "New Haven"}], "description": "Served from our Orange, CT office. We cover every town in New Haven County from coastal Branford and Madison to inland Woodbridge and Cheshire - delivering expert remodeling across the region.", "extra_towns": ["Cheshire", "Ansonia", "Beacon Falls", "Bethany", "Derby", "East Haven", "Meriden", "Middlebury", "Naugatuck", "North Branford", "North Haven", "Oxford", "Prospect", "Seymour", "Southbury", "Wallingford", "Waterbury", "West Haven", "Wolcott"]}], "subtitle": "We serve 16 towns across Fairfield County and New Haven County with dedicated local crews, covering every community from Greenwich to Madison and headquartered in Orange, CT.", "note_link_url": "/contact/", "highlight_text": "Service Areas", "note_link_text": "Contact our Connecticut remodeling team"}', updated_at = NOW() WHERE id = 8346;
