UPDATE sections SET data = '{"rows": [{"label": "Basic trim package, one room (casing and base)", "price": "$1,500 – $4,000"}, {"label": "Crown molding, single room", "price": "$800 – $2,500"}, {"label": "Crown molding, whole home (colonial, 2,000 sq ft)", "price": "$4,000 – $10,000"}, {"label": "Wainscoting or board and batten, one room", "price": "$2,000 – $5,500"}, {"label": "Custom built-in bookcase or shelving unit", "price": "$3,000 – $8,000"}, {"label": "Built-in window seat with storage", "price": "$2,500 – $6,000"}, {"label": "Fireplace surround and mantel", "price": "$2,000 – $7,000"}, {"label": "Coffered ceiling, one room", "price": "$4,000 – $12,000"}, {"label": "Whole-home millwork package", "price": "$10,000 – $40,000+"}], "title": "Interior Carpentry Cost in Connecticut", "columns": ["Scope", "Cost Range"], "subtitle": "Interior carpentry in Connecticut runs $75 to $150 per hour for labor, with total project costs determined by scope, complexity, and materials. Below are typical ranges for common project types. Ranges are illustrative for typical Connecticut projects. Final pricing depends on scope, materials, site conditions, and permit fees. Detailed written estimate provided before any work begins.", "below_table_note": "Materials are priced separately and vary based on wood species, profile complexity, and whether standard stock or custom-milled pieces are required. We provide a written estimate with labor and material costs broken out clearly before work begins."}', updated_at = NOW() WHERE id = 8430;
