UPDATE sections SET data = '{"rows": [{"label": "Basic", "notes": "Framing, drywall, basic flooring, lighting", "price": "$25,000 - $45,000"}, {"label": "Mid-Range", "notes": "Multiple rooms, upgraded flooring, bathroom rough-in", "price": "$45,000 - $70,000"}, {"label": "High-End", "notes": "Full bathroom, wet bar, custom built-ins", "price": "$70,000 - $100,000+"}], "title": "Basement Finishing Costs in Westport, CT", "columns": ["Tier", "Scope", "Typical Range"], "subtitle": "For homes in or near flood zones, we address drainage and moisture management before framing begins. That work adds to overall project cost but is not optional if you want a finished basement that holds up. Ranges are illustrative for typical Connecticut projects. Final pricing depends on scope, materials, site conditions, and permit fees. Detailed written estimate provided before any work begins."}', updated_at = NOW() WHERE id = 8463;
UPDATE sections SET data = '{"rows": [{"label": "Solid Hardwood", "notes": "Living rooms, dining rooms, bedrooms", "price": "$12 - $25"}, {"label": "Engineered Hardwood", "notes": "Basements, moisture-prone areas", "price": "$8 - $18"}, {"label": "Luxury Vinyl Plank", "notes": "Basements, kitchens, high-traffic", "price": "$6 - $14"}, {"label": "Tile", "notes": "Bathrooms, kitchens, entryways", "price": "$12 - $25"}, {"label": "Carpet", "notes": "Bedrooms, basement rec rooms", "price": "$4 - $12"}], "title": "Flooring Costs in Westport, CT", "columns": ["Material", "Best For", "Installed Cost/sq ft"], "subtitle": "Many 1960s Westport colonials have original hardwood floors under carpet or vinyl that are worth refinishing. We assess what is there and give you a straight answer on whether to refinish or replace. Ranges are illustrative for typical Connecticut projects. Final pricing depends on scope, materials, site conditions, and permit fees. Detailed written estimate provided before any work begins."}', updated_at = NOW() WHERE id = 8464;
UPDATE sections SET data = '{"rows": [{"label": "Bump-Out", "notes": "Single-room expansion, 100-200 sq ft", "price": "$150 - $400/sq ft"}, {"label": "Single-Story", "notes": "Family room, sunroom, or garage conversion", "price": "$150 - $400/sq ft"}, {"label": "Second-Story", "notes": "Full second floor with structural support", "price": "$200 - $400/sq ft"}], "title": "Home Additions Costs in Westport, CT", "columns": ["Type", "Scope", "Typical Range"], "subtitle": "Westport additions in coastal and flood zone areas may require elevation to Base Flood Elevation, adding to project scope and cost. Ranges are illustrative for typical Connecticut projects. Final pricing depends on scope, materials, site conditions, and permit fees. Detailed written estimate provided before any work begins."}', updated_at = NOW() WHERE id = 8465;
UPDATE sections SET data = '{"rows": [{"label": "Per Square Foot", "notes": "Walls, ceilings, trim, proper surface prep", "price": "$3 - $6/sq ft"}, {"label": "Single Room", "notes": "Average bedroom or living room", "price": "$800 - $2,500"}, {"label": "Whole Home", "notes": "Full interior, all rooms, trim, doors", "price": "$8,000 - $25,000+"}], "title": "Interior Painting Costs in Westport, CT", "columns": ["Scope", "Details", "Typical Range"], "subtitle": "Ranges are illustrative for typical Connecticut projects. Final pricing depends on scope, materials, site conditions, and permit fees. Detailed written estimate provided before any work begins."}', updated_at = NOW() WHERE id = 8466;
UPDATE sections SET data = '{"rows": [{"label": "Hourly Rate", "notes": "Custom trim, built-ins, shelving, wainscoting", "price": "$75 - $150/hour"}, {"label": "Crown Molding", "notes": "Per linear foot, installed", "price": "$8 - $25/LF"}, {"label": "Custom Built-Ins", "notes": "Bookcases, window seats, mudroom storage", "price": "$3,000 - $15,000+"}], "title": "Interior Carpentry Costs in Westport, CT", "columns": ["Scope", "Details", "Typical Range"], "subtitle": "Postwar Westport colonials and Cape Cods often have original trim profiles and built-in cabinetry that homeowners want preserved or matched during renovation. Custom millwork to replicate these details adds both material cost and lead time compared to standard stock profiles. Ranges are illustrative for typical Connecticut projects. Final pricing depends on scope, materials, site conditions, and permit fees. Detailed written estimate provided before any work begins."}', updated_at = NOW() WHERE id = 8467;
UPDATE sections SET data = '{"rows": [{"label": "Attic Conversions", "notes": "Framing, insulation, electrical, flooring, egress", "price": "$50,000 - $150,000"}, {"label": "Decks and Porches", "notes": "Wood, composite, or PVC with railings and permits", "price": "$15,000 - $75,000"}, {"label": "Design and Planning", "notes": "Layout, material selection, 3D rendering, permit drawings", "price": "$2,500 - $15,000"}, {"label": "Comfort and Accessibility", "notes": "Grab bars, walk-in showers, widened doorways, ramps", "price": "$5,000 - $50,000"}, {"label": "Insurance Reconstruction", "notes": "Fire, water, storm damage rebuilds with carrier coordination", "price": "$25,000 - $250,000+"}], "title": "Additional Service Costs in Westport, CT", "columns": ["Service", "Details", "Typical Range"], "subtitle": "Ranges are illustrative for typical Connecticut projects. Final pricing depends on scope, materials, site conditions, and permit fees. Detailed written estimate provided before any work begins."}', updated_at = NOW() WHERE id = 8468;
UPDATE sections SET data = '{"title": "Fairfield County Towns We Also Serve", "eyebrow": "Nearby Towns", "counties": [{"url": "/fairfield-county/", "name": "Fairfield County", "image": "https://builtwell-api.petararsic.rs/storage/media/cgIlih2qYCeb09TCKKqHfgQmqX4dKGCLC7nBlbR4.webp", "phone": "(203) 919-9616", "towns": ["Greenwich", "Stamford", "Norwalk", "Westport", "Darien", "New Canaan", "Fairfield", "Ridgefield", "Trumbull"], "cta_label": "Learn more about Fairfield County", "image_alt": "Fairfield County Connecticut towns served by BuiltWell CT", "town_links": {"Greenwich": "/fairfield-county/greenwich-ct/"}, "description": "Served by our Fairfield County Service Area Team. We cover every town in the county with dedicated local crews who know the housing stock and building departments.", "extra_towns": ["Bethel", "Bridgeport", "Brookfield", "Danbury", "Easton", "Monroe", "New Fairfield", "Newtown", "Redding", "Shelton", "Sherman", "Stratford", "Weston", "Wilton"], "current_town": "Westport"}], "subtitle": "Beyond Westport, we serve homeowners throughout Fairfield County. Our team handles remodeling projects in Darien, Fairfield, Norwalk, Ridgefield, New Canaan, Stamford, and Greenwich, as well as additional towns across the county.", "highlight_text": "We Also Serve"}', updated_at = NOW() WHERE id = 8474;
