INSERT INTO sections (id, page_id, type, data, sort_order, is_active, created_at, updated_at)
VALUES (8516, 132, 'hero', '{"eyebrow": null, "overlay": {"opacity": 0.72}, "headline": "Accessibility Statement", "subheadline": "BuiltWell CT is committed to making this website accessible to every Connecticut homeowner, including users with disabilities.", "background_image": "/portfolio/builtwell-team-client-arrival-ct.jpeg"}', 0, 1, NOW(), NOW())
ON DUPLICATE KEY UPDATE data=VALUES(data), sort_order=VALUES(sort_order), is_active=VALUES(is_active), updated_at=NOW();
INSERT INTO sections (id, page_id, type, data, sort_order, is_active, created_at, updated_at)
VALUES (8517, 132, 'rich_text', '{"title": "Our Commitment", "content": "BuiltWell CT is committed to providing a website that is accessible to the widest possible audience, regardless of ability or technology. We work to follow the Web Content Accessibility Guidelines (WCAG) 2.1 Level AA, which are the international standard for digital accessibility.\\\\n\\\\nThis statement applies to content published on builtwellct.com. We continually review the site, address issues as they are identified, and prioritize fixes for any barrier that prevents a person from accessing essential information about our remodeling services or contacting us about a project."}', 1, 1, NOW(), NOW())
ON DUPLICATE KEY UPDATE data=VALUES(data), sort_order=VALUES(sort_order), is_active=VALUES(is_active), updated_at=NOW();
INSERT INTO sections (id, page_id, type, data, sort_order, is_active, created_at, updated_at)
VALUES (8518, 132, 'rich_text', '{"title": "Measures We Take", "content": "We design and build pages with semantic HTML, descriptive link text, and properly labeled form fields. We provide alternative text for meaningful images and captions where needed. Color contrast is reviewed against WCAG AA thresholds. Interactive elements are operable with a keyboard, and the site is tested with screen readers including VoiceOver and NVDA. Where third-party content (such as embedded maps or video) does not meet our accessibility standards, we provide alternative ways to access the same information."}', 2, 1, NOW(), NOW())
ON DUPLICATE KEY UPDATE data=VALUES(data), sort_order=VALUES(sort_order), is_active=VALUES(is_active), updated_at=NOW();
INSERT INTO sections (id, page_id, type, data, sort_order, is_active, created_at, updated_at)
VALUES (8519, 132, 'rich_text', '{"title": "Known Limitations", "content": "No website is fully free of accessibility issues, and we do not claim that this one is. If you encounter a barrier on builtwellct.com, please contact us using the methods below. We will do our best to provide the requested information in a format that works for you within a reasonable time, generally within five business days."}', 3, 1, NOW(), NOW())
ON DUPLICATE KEY UPDATE data=VALUES(data), sort_order=VALUES(sort_order), is_active=VALUES(is_active), updated_at=NOW();
INSERT INTO sections (id, page_id, type, data, sort_order, is_active, created_at, updated_at)
VALUES (8520, 132, 'rich_text', '{"title": "Contact Us About Accessibility", "content": "If you experience any difficulty accessing content on this site, please contact us:\\\\n\\\\nBuiltWell CT (Legacy of Clean LLC d/b/a BuiltWell CT)\\\\n206A Boston Post Road, Orange, CT 06477\\\\nPhone: (203) 466-9148\\\\nEmail: info@builtwellct.com\\\\n\\\\nPlease describe the page or feature you were trying to access, the assistive technology or browser you were using, and the issue you encountered. We respond to accessibility inquiries within five business days."}', 4, 1, NOW(), NOW())
ON DUPLICATE KEY UPDATE data=VALUES(data), sort_order=VALUES(sort_order), is_active=VALUES(is_active), updated_at=NOW();
INSERT INTO sections (id, page_id, type, data, sort_order, is_active, created_at, updated_at)
VALUES (8521, 132, 'rich_text', '{"title": "Physical Accessibility of Our Services", "content": "BuiltWell CT also offers home modifications that improve in-home accessibility, including grab bars, walk-in showers, ramps with proper slope, lever-style hardware, and aging-in-place upgrades. Information about these services is available on our [Comfort and Accessibility Remodeling](/comfort-accessibility-remodeling/) page."}', 5, 1, NOW(), NOW())
ON DUPLICATE KEY UPDATE data=VALUES(data), sort_order=VALUES(sort_order), is_active=VALUES(is_active), updated_at=NOW();
INSERT INTO sections (id, page_id, type, data, sort_order, is_active, created_at, updated_at)
VALUES (8522, 132, 'rich_text', '{"title": "Updates to This Statement", "content": "This statement was last updated on May 1, 2026. We review and update it as the site changes and as we receive feedback from users. The current version is always published at /accessibility/."}', 6, 1, NOW(), NOW())
ON DUPLICATE KEY UPDATE data=VALUES(data), sort_order=VALUES(sort_order), is_active=VALUES(is_active), updated_at=NOW();
INSERT INTO sections (id, page_id, type, data, sort_order, is_active, created_at, updated_at)
VALUES (8523, 13, 'rich_text', '{"align": "left", "title": "Why There''s No Gallery Yet", "content": "BuiltWell CT was founded by a contractor with 15+ years of hands-on remodeling and restoration experience, but the BuiltWell brand itself is brand new. Rather than fill this page with stock photos or borrowed work, we''re documenting our own projects from the first day forward. The first kitchens, bathrooms, basements, and additions are in progress across Fairfield and New Haven Counties right now. Each completed project will be added here with photos, scope, timeline, and the homeowner''s own words.\\\\n\\\\nIf you''d rather see a contractor''s actual recent work before you sign anything, we get it. Schedule a free consultation and we''ll walk you through our process and references from prior remodeling work, show you exactly how we run a job, and answer any question you have. The portfolio you see here in six months will be built from the homeowners who hired us today.", "eyebrow": "Brand New, Built Right", "spacing": "normal", "surface": "cream", "style_variant": "default", "highlight_text": "No Gallery Yet", "container_width": "narrow"}', 1, 1, NOW(), NOW())
ON DUPLICATE KEY UPDATE data=VALUES(data), sort_order=VALUES(sort_order), is_active=VALUES(is_active), updated_at=NOW();
INSERT INTO sections (id, page_id, type, data, sort_order, is_active, created_at, updated_at)
VALUES (8524, 111, 'rich_text', '{"align": "left", "title": "Why You Don''t See Polished Case Studies Yet", "content": "BuiltWell CT is a brand-new Connecticut remodeling company. Rather than backfill this page with stock photos, borrowed work, or generic before-and-afters, we''re documenting our own projects from day one — with real measurements, scope notes, signed permits, photos at each phase, and the homeowner''s own words at the end.\\\\n\\\\nThe first kitchens, bathrooms, basements, and additions under the BuiltWell name are in progress right now. Each completed project will be added to this page with full scope, timeline, materials, and what we learned. If you would rather see real recent work before you sign anything, schedule a free consultation. We will bring references from prior remodeling and restoration work, walk you through scope, and show you exactly how we run a job. The case studies you see here in six months will be built from the homeowners who hired us today.", "eyebrow": "Brand New, Built Right", "spacing": "normal", "surface": "cream", "style_variant": "default", "highlight_text": "Yet", "container_width": "narrow"}', 2, 1, NOW(), NOW())
ON DUPLICATE KEY UPDATE data=VALUES(data), sort_order=VALUES(sort_order), is_active=VALUES(is_active), updated_at=NOW();

