ge":"$$","hasCredential":{"@type":"EducationalOccupationalCredential","credentialCategory":"Home Improvement Contractor License","identifier":"0668405"},"sameAs":["https:\\\\/\\\\/instagram.com\\\\/builtwellct","https:\\\\/\\\\/linkedin.com\\\\/company\\\\/builtwellct","https:\\\\/\\\\/youtube.com\\\\/@builtwellct","https:\\\\/\\\\/facebook.com\\\\/builtwellct"],"foundingDate":"2010","slogan":"The Last Contractor You''ll Hire"}]', updated_at = NOW() WHERE id = 2;
UPDATE pages SET schema_overrides = '[{"@context":"https:\\\\/\\\\/schema.org","@type":"BreadcrumbList","@id":"https:\\\\/\\\\/buildwellct.com\\\\/bathroom-remodeling\\\\/#breadcrumb","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https:\\\\/\\\\/buildwellct.com\\\\/"},{"@type":"ListItem","position":2,"name":"Services","item":"https:\\\\/\\\\/buildwellct.com\\\\/services\\\\/"},{"@type":"ListItem","position":3,"name":"Bathroom Remodeling","item":"https:\\\\/\\\\/buildwellct.com\\\\/bathroom-remodeling\\\\/"}]},{"@context":"https:\\\\/\\\\/schema.org","@type":"Service","name":"Bathroom Remodeling","description":"Professional bathroom remodeling in Connecticut including walk-in showers, vanities, tile, waterproofing, plumbing, electrical, and all permit coordination. Serving Fairfield and New Haven Counties.","provider":{"@type":"Organization","name":"BuiltWell CT","url":"https:\\\\/\\\\/buildwellct.com","telephone":["(203) 919-9616","(203) 466-9148"],"address":{"@type":"PostalAddress","streetAddress":"206A Boston Post Road","addressLocality":"Orange","addressRegion":"CT","postalCode":"06477","addressCountry":"US"}},"areaServed":[{"@type":"AdministrativeArea","name":"Fairfield County, Connecticut"},{"@type":"AdministrativeArea","name":"New Haven County, Connecticut"}],"serviceType":"Bathroom Remodeling","offers":{"@type":"AggregateOffer","lowPrice":"15000","highPrice":"120000","priceCurrency":"USD"}},{"@context":"https:\\\\/\\\\/schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"Do I need a permit for a bathroom remodel in Connecticut?","acceptedAnswer":{"@type":"Answer","text":"Yes. Bathroom remodeling work that involves plumbing, electrical, or structural modifications requires permits in all Connecticut towns. Replacing a tub with a walk-in shower almost always requires a building permit, and the electrical work involved in updating bathroom lighting and installing GFCI outlets requires an electrical permit in most municipalities. Even renovations that appear cosmetic can trigger permit requirements if they involve any licensed trade work. Some towns issue a single permit covering all trades; others require separate filings for building, electrical, and plumbing, each with their own inspections. We handle all permit applications and inspection coordination as part of the project; you don''t need to manage that process separately."}},{"@type":"Question","name":"How long does a bathroom remodel take in CT?","acceptedAnswer":{"@type":"Answer","text":"Most full bathroom renovations in Connecticut complete in three to six weeks of active construction. Basic updates such as a new vanity, fixtures, flooring, and paint without major structural or plumbing changes run two to three weeks. Full gut renovations with custom tile, a new shower enclosure, and relocated plumbing typically take five to six weeks. Projects that involve layout changes, plumbing relocation, or expanding the footprint of the bathroom extend beyond that. We provide a specific project schedule in your written proposal so you know your expected start date, key milestones, and projected completion before work begins."}},{"@type":"Question","name":"Can I use the bathroom during a remodel?","acceptedAnswer":{"@type":"Answer","text":"Not the bathroom being renovated. We seal off the work area with dust barriers for safety and dust control, and the space won''t be functional until the project is complete. If you have a second bathroom in your home, you''ll be able to use that throughout the project. If the bathroom being renovated is your only bathroom, we''ll discuss that with you during the planning phase and work through a realistic approach, whether that means sequencing the work to restore basic function as quickly as possible or identifying alternatives. We make sure you understand exactly what access looks like before construction begins."}},{"@type":"Question","name":"What''s the difference between a bathroom refresh and a full remodel?","acceptedAnswer":{"@type":"Answer","text":"A bathroom refresh updates surfaces and fixtures without opening walls or changing the layout. It typically includes a new vanity and countertop, updated faucets and fixtures, new flooring, paint, and sometimes new lighting. The plumbing supply and drain lines stay in place, and nothing structural changes. A full remodel involves gutting the space to the studs, which allows for layout changes, proper waterproofing behind tile, subfloor repairs, plumbing relocation, and a complete redesign of the space. Refreshes generally start around $15,000. Full gut renovations start around $25,000 and go up from there based on scope and material selections. The right choice depends on the condition of your current bathroom and what you''re trying to accomplish."}},{"@type":"Question","name":"Can you install a walk-in shower in place of a bathtub?","acceptedAnswer":{"@type":"Answer","text":"Yes. Tub-to-shower conversions are one of our most commonly requested projects, and we handle every aspect: plumbing reconfiguration, drain installation with proper slope for barrier-free entry, waterproofing membrane, tile, and the shower enclosure itself. We''ll assess whether the existing floor framing needs reinforcement for the new drain location and whether the subfloor can support the tile system you want. Walk-in shower installations require a building permit in Connecticut, which we handle as part of the project. If the bathroom currently has only one tub and you''re replacing it with a shower, we''ll discuss that during the consultation, particularly if resale value is a consideration, since some buyers prefer at least one tub in the home."}},{"@type":"Question","name":"Does a bathroom remodel increase home value in Connecticut?","acceptedAnswer":{"@type":"Answer","text":"Yes. Bathroom remodeling consistently ranks among the highest-ROI home improvements in Connecticut. A mid-range bathroom renovation typically returns 60 to 70 percent of the investment at resale, and in competitive Fairfield County markets like Greenwich, Westport, and Darien, updated bathrooms are often expected by buyers rather than viewed as a bonus. The return depends on the scope of the project, the quality of materials used, and how the finished bathroom compares to other homes in your neighborhood. Over-improving relative to neighboring homes can reduce the percentage return. We can help you make material and scope decisions that balance what you want to live with and what makes sense for your home''s market position."}}]},{"@context":"https:\\\\/\\\\/schema.org","@type":"HomeAndConstructionBusiness","name":"BuiltWell CT","url":"https:\\\\/\\\\/buildwellct.com","telephone":["(203) 919-9616","(203) 466-9148"],"address":{"@type":"PostalAddress","streetAddress":"206A Boston Post Road","addressLocality":"Orange","addressRegion":"CT","postalCode":"06477","addressCountry":"US"},"geo":{"@type":"GeoCoordinates","latitude":41.2784,"longitude":-73.0257},"areaServed":[{"@type":"AdministrativeArea","name":"Fairfield County, CT"},{"@type":"AdministrativeArea","name":"New Haven County, CT"}],"priceRange":"$$","image":"https:\\\\/\\\\/buildwellct.com\\\\/images\\\\/builtwell-og.jpg"}]', updated_at = NOW() WHERE id = 6;
