UPDATE pages SET schema_overrides = '[{"@context":"https:\\\\/\\\\/schema.org","@type":"BreadcrumbList","@id":"https:\\\\/\\\\/buildwellct.com\\\\/home-additions\\\\/#breadcrumb","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https:\\\\/\\\\/buildwellct.com\\\\/"},{"@type":"ListItem","position":2,"name":"Services","item":"https:\\\\/\\\\/buildwellct.com\\\\/services\\\\/"},{"@type":"ListItem","position":3,"name":"Home Additions","item":"https:\\\\/\\\\/buildwellct.com\\\\/home-additions\\\\/"}]},{"@context":"https:\\\\/\\\\/schema.org","@type":"Service","name":"Home Additions","description":"Home additions in Connecticut including room additions, second stories, garage conversions, foundation work, framing, and all permit coordination. Serving Fairfield and New Haven Counties.","provider":{"@type":"Organization","name":"BuiltWell CT","url":"https:\\\\/\\\\/buildwellct.com","telephone":["(203) 919-9616","(203) 466-9148"],"address":{"@type":"PostalAddress","streetAddress":"206A Boston Post Road","addressLocality":"Orange","addressRegion":"CT","postalCode":"06477","addressCountry":"US"}},"areaServed":[{"@type":"AdministrativeArea","name":"Fairfield County, Connecticut"},{"@type":"AdministrativeArea","name":"New Haven County, Connecticut"}],"serviceType":"Home Additions","offers":{"@type":"AggregateOffer","lowPrice":"80000","highPrice":"300000","priceCurrency":"USD"}},{"@context":"https:\\\\/\\\\/schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"How much does a home addition cost in Connecticut?","acceptedAnswer":{"@type":"Answer","text":"Home additions in Connecticut cost between $150 and $400 per square foot all-in, with most projects falling between $80,000 and $300,000. The type of addition is the biggest cost driver. A first-floor bedroom addition on a straightforward lot with a standard foundation will come in toward the lower end of the range. A second-story addition that requires reinforcing the existing structure, or a project with complex rooflines, custom finishes, and premium materials, will trend toward the higher end or above it. Other factors that affect cost in Connecticut specifically include site conditions like ledge rock or high water tables, permit fees that vary by town, and whether your project requires zoning board approval or historic commission review. We provide a detailed written estimate after the consultation and site visit, with exact numbers rather than ranges."}},{"@type":"Question","name":"How long does a home addition take to build?","acceptedAnswer":{"@type":"Answer","text":"Plan for a total timeline of four to six months from the start of design to project completion. Permit review in Connecticut typically takes two to six weeks depending on the town and the complexity of the application. Active construction runs eight to sixteen weeks from permit approval. Second-story additions, complex roofline work, and projects that require zoning board review trend toward the longer end of both phases. We give you a specific project schedule before construction begins. The schedule shows each phase of work, when inspections are required, and the sequence of trades so you know what to expect and when. We update you daily during the build."}},{"@type":"Question","name":"Do I need zoning approval for a home addition in CT?","acceptedAnswer":{"@type":"Answer","text":"Most home additions in Connecticut require at least a building permit, and many also require zoning approval. Zoning review is typically triggered when an addition changes the footprint of the structure, increases lot coverage, or places the building closer to property lines than the town''s setback rules allow. Towns across Fairfield and New Haven counties each have their own setback distances, maximum lot coverage percentages, and height restrictions. Greenwich, Darien, and New Canaan are among the most restrictive. Some towns also have additional review layers: homes in historic districts in New Haven, Guilford, and Ridgefield may need approval from a historic commission before the building department will issue a permit. We research your property''s zoning status and applicable rules before design begins. If your project requires a variance or special permit, we work with you through that process."}},{"@type":"Question","name":"Can I stay in my home during an addition project?","acceptedAnswer":{"@type":"Answer","text":"Yes. Most homeowners remain in their homes throughout the addition process. The tie-in to your existing structure is planned and sequenced carefully so your home stays dry and livable while work is underway. We install temporary weather protection at all connection points and maintain dust barriers inside. The level of disruption depends on the type of addition. A first-floor addition on the side of the house is less disruptive than a second-story addition that requires work above your living space. We walk through what to expect before construction begins so there are no surprises."}},{"@type":"Question","name":"What types of home additions do you build?","acceptedAnswer":{"@type":"Answer","text":"We build bedroom additions and primary suite additions, family room and living space additions, sunrooms and three-season rooms, first-floor additions that expand the main level without stair complications, second-story additions over an existing first-floor footprint, kitchen bump-outs that add 100 to 200 square feet of working space, garage conversions into finished living space, and attached garage additions with or without living space above. Each type has different structural, permitting, and cost considerations that we review during the consultation."}},{"@type":"Question","name":"Will the addition match the rest of my home?","acceptedAnswer":{"@type":"Answer","text":"That is one of the primary goals of every addition we build. The addition is designed to integrate structurally and visually with your existing home. That means matching rooflines, siding profiles, window styles, and interior trim so the new space looks like it was always part of the house. We coordinate with architects and structural engineers as part of the project scope to ensure the design achieves this. During the planning phase, we identify specific materials needed to match your existing finishes and source them before construction begins."}}]},{"@context":"https:\\\\/\\\\/schema.org","@type":"HomeAndConstructionBusiness","name":"BuiltWell CT","url":"https:\\\\/\\\\/buildwellct.com","telephone":["(203) 919-9616","(203) 466-9148"],"address":{"@type":"PostalAddress","streetAddress":"206A Boston Post Road","addressLocality":"Orange","addressRegion":"CT","postalCode":"06477","addressCountry":"US"},"geo":{"@type":"GeoCoordinates","latitude":41.2784,"longitude":-73.0257},"areaServed":[{"@type":"AdministrativeArea","name":"Fairfield County, CT"},{"@type":"AdministrativeArea","name":"New Haven County, CT"}],"priceRange":"$$","image":"https:\\\\/\\\\/buildwellct.com\\\\/images\\\\/builtwell-og.jpg"}]', updated_at = NOW() WHERE id = 16;
